<div class="orth-section-intro"><div><h3>Plan de tratamiento</h3><p>Objetivos y fases definidos por el profesional, con versiones conservadas.</p></div><?php if(!empty($case['plan_id']) && can('treatments')): ?><a class="button secondary small" href="<?= e(url('/admin/treatments?patient_id='.$case['patient_id'])) ?>">Presupuesto y tratamientos <?= icon('arrow',15) ?></a><?php endif; ?></div>
<?php if($canWrite): ?><details class="panel orth-form-panel"<?= !$plans?' open':'' ?>><summary><?= icon('heart',18) ?><span><?= $plans?'Proponer una nueva versión del plan':'Preparar el plan clínico' ?></span><small>Conserva las versiones anteriores</small></summary><div class="orth-section-heading"><div><span class="orth-kicker"><?= $plans?'PROPONER UNA NUEVA VERSIÓN':'PLANIFICACIÓN INICIAL' ?></span><h3>Plan clínico individual</h3></div><span class="orth-status"><?= e($orthoLabel($case['type_key'] ?? '',$typeNames)) ?></span></div><form method="post" class="form-grid orth-panel-body orth-plan-form" data-orth-dirty data-loading><?php $orthoFields('plan',$case); ?><input type="hidden" name="previous_id" value="<?= (int)($plans[0]['id'] ?? 0) ?>"><?php choose('type_key','Tipo de tratamiento',$typeNames,$plan['type_key'] ?? $case['type_key']); field('appliance','Aparatología seleccionada',$plan['appliance'] ?? $case['appliance'],'text',false,'maxlength="200"'); area('objectives','Objetivos clínicos',$plan['objectives'] ?? $diagnosis['objectives'] ?? '',true); area('phases','Fases previstas · una por línea',$plan['phases'] ?? ''); area('procedures','Procedimientos planificados',$plan['procedures'] ?? ''); field('estimated_start','Fecha estimada de inicio',$plan['estimated_start'] ?? $case['start_date'] ?? '','date',false); field('estimated_months','Duración estimada (meses)',$plan['estimated_months'] ?? $case['estimated_months'] ?? '','number',false,'min="1" max="120"'); field('control_interval_days','Frecuencia de controles (días)',$plan['control_interval_days'] ?? $case['control_interval_days'] ?? 30,'number',true,'min="1" max="730"'); choose('status','Guardar como',['draft'=>'Borrador','authorized'=>'Autorizado por el profesional'],'draft'); area('completion_criteria','Criterios clínicos para finalizar',$plan['completion_criteria'] ?? '',true); area('retention_plan','Plan de retención e indicaciones',$plan['retention_plan'] ?? ''); area('change_reason','Motivo de esta versión',''); ?><label class="orth-check full"><input type="checkbox" name="confirm_authorization" value="1">He revisado y autorizo este plan, si se guarda como autorizado.</label><button class="button full">Guardar versión del plan</button></form></details><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><div><h3>Versiones del plan</h3><p>Compara el contenido clínico y consulta quién autorizó cada modificación.</p></div></div><?php if(!$plans): $orthoEmpty('La planificación aún no ha comenzado','El primer plan y sus siguientes versiones aparecerán aquí.','heart'); else: ?><div class="orth-plan-compare-tools"><label>Comparar versiones<select data-orth-plan-first aria-label="Primera versión"><?php foreach($plans as $i=>$entry): ?><option value="<?= (int)$entry['id'] ?>">Versión <?= count($plans)-$i ?> · <?= local_date($entry['created_at'] ?? null,'d/m/Y') ?></option><?php endforeach; ?></select></label><label>Con la versión<select data-orth-plan-second aria-label="Segunda versión"><?php foreach($plans as $i=>$entry): ?><option value="<?= (int)$entry['id'] ?>"<?= $i===1?' selected':'' ?>>Versión <?= count($plans)-$i ?> · <?= local_date($entry['created_at'] ?? null,'d/m/Y') ?></option><?php endforeach; ?></select></label><button type="button" class="button secondary" data-orth-plan-compare<?= count($plans)<2?' disabled':'' ?>>Comparar</button></div><div class="orth-plan-comparison" data-orth-plan-comparison hidden aria-live="polite"></div><div class="orth-records"><?php foreach($plans as $index=>$entry): $data=$entry['data'] ?? []; ?><details class="orth-record" data-orth-plan="<?= (int)$entry['id'] ?>"<?= $index===0?' open':'' ?>><summary><span><strong>Versión <?= count($plans)-$index ?></strong><small><?= local_date($entry['created_at'] ?? null) ?> · <?= e($entry['author'] ?? $entry['professional'] ?? '') ?></small></span><span class="orth-status <?= ($entry['status'] ?? '')==='authorized'?'active':'' ?>"><?= ($entry['status'] ?? '')==='authorized'?'Autorizado':'Borrador' ?></span></summary><div class="orth-record-body"><dl class="orth-definition-list"><?php foreach(['objectives'=>'Objetivos','phases'=>'Fases previstas','procedures'=>'Procedimientos','estimated_start'=>'Inicio estimado','estimated_months'=>'Duración estimada (meses)','control_interval_days'=>'Frecuencia de controles (días)','completion_criteria'=>'Criterios para finalizar','retention_plan'=>'Retención','change_reason'=>'Motivo de la versión'] as $key=>$title): ?><div><dt><?= e($title) ?></dt><dd><?= nl2br(e($data[$key] ?? ($key==='change_reason' ? ($entry['change_reason'] ?? 'Sin registrar'):'Sin registrar'))) ?></dd></div><?php endforeach; ?></dl><p class="orth-help">Autorización: <?= !empty($entry['authorized_at'])?local_date($entry['authorized_at']).' · '.e($entry['authorized_by_name'] ?? $entry['author'] ?? ''):'Pendiente' ?></p><?php if($canWrite && ($entry['status'] ?? '')==='draft'): ?><form method="post" class="orth-inline-form" data-confirm="¿Autorizar esta versión del plan? El contenido conservará su registro histórico."><?php $orthoFields('authorize_plan',$case); ?><input type="hidden" name="plan_id" value="<?= (int)$entry['id'] ?>"><input type="hidden" name="confirm_authorization" value="1"><button class="button secondary small">Autorizar esta versión</button></form><?php endif; ?></div></details><?php endforeach; ?></div><?php endif; ?></section>
<?php if($phases): ?><section class="panel"><div class="orth-section-heading"><h3>Fases del tratamiento</h3><p>La secuencia responde al plan autorizado.</p></div><div class="orth-records"><?php foreach($phases as $phase): ?><details class="orth-record"><summary><span><strong><?= e($phase['stage_name'] ?? $phase['name'] ?? '') ?></strong><small><?= e($phase['notes'] ?? '') ?></small></span><?= badge($phase['status']) ?></summary><?php if($canWrite): ?><form method="post" class="form-grid orth-record-body" data-loading><?php $orthoFields('phase',$case); ?><input type="hidden" name="stage_id" value="<?= (int)$phase['id'] ?>"><?php choose('status','Estado',['pending'=>'Pendiente','in_progress'=>'En curso','completed'=>'Completada','not_applicable'=>'No aplica','needs_review'=>'Requiere revisión'],$phase['status']); area('notes','Observaciones',$phase['notes'] ?? ''); ?><button class="button secondary small">Actualizar fase</button></form><?php endif; ?></details><?php endforeach; ?></div></section><?php endif; ?>

<?php if($canWrite): ?><details class="panel orth-form-panel"><summary><?= icon('plus',18) ?><span>Añadir una fase individual al seguimiento</span></summary><form method="post" class="form-grid orth-panel-body" data-orth-dirty data-loading><?php $orthoFields('create_stage',$case); field('stage_name','Nombre de la fase','','text',true,'maxlength="150"'); area('notes','Propósito y observaciones'); ?><button class="button secondary">Añadir fase</button></form></details><?php endif; ?>
